 "previous_turns_for_context_only": [],
 "turns": [
  {
   "id": "M1:T1",
   "speaker": "Analyst",
   "act": "open",
   "guide": "Analyst opens the meeting about Internetworking of Content Delivery Networks (meeting 1 of 1, kickoff)."
  },
  {
   "id": "M1:T2",
   "speaker": "Client",
   "act": "context",
   "guide": "Client gives the project background below, in their own words.",
   "content": [
    {
     "text": "The final product enabling CDN peering assists in coordinated and cooperative content delivery via internetworking among distinct CDNs to allow providers to rapidly \"scale-out\" to meet both flash crowds and anticipated increases in demand, and remove the need for a single CDN to provision resources. An ad-hoc or planned peering of CDNs requires fundamental research to be undertaken to address the core problems of measuring and disseminating load information, performing request assignment and redirection, enabling content replication and determining appropriate compensation among participants on a geographically distributed \"Internet\" scale. In contrast to a single CDN, for which these issues are deeply interrelated and co-dependent, the main thrust for the final product enabling CDN peering is to consider them in a coordinated and cooperative manner among many peered CDNs, whilst satisfying the complex multi-dimensional constraints placed on each individual provider.",
     "role": "background"
    }
   ]
  },
  {
   "id": "M1:T3",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'trigger' and asks about it."
  },
  {
   "id": "M1:T4",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Service registration is triggered when either one of the following occurs: (a) resources are available as a provider starts operating; (b) previously registered resource information needs to be updated; (c) available local resource information is required in the event of traffic surges; and (d) local and delegated external resource information is to be encapsulated in an SR instance included in an established peering arrangement.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'service registration' and asks about it."
  },
  {
   "id": "M1:T6",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The format for service information description is defined",
     "role": "statement"
    },
    {
     "text": "The interaction protocol between Web Server-SR, SR-mediator is defined.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T7",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Resource provisioning, delegation and reservation policies are in place",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T8",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T9",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "There is an established norm that any resource failure will be reported",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T10",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'trigger' and asks about it."
  },
  {
   "id": "M1:T11",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "It is invoked when a (primary) CDN realizes that it cannot handle a part of the workload on its WS(s).",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T12",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'trigger'."
  },
  {
   "id": "M1:T13",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T14",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'exceptions' and asks about it."
  },
  {
   "id": "M1:T15",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Malicious requests are detected and rejected.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T16",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Web servers have already replicated necessary content.",
     "role": "statement"
