     "text": "The format of service requirements is defined.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T19",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
